def imports(m):
    p = m.replace('.', '/') + '.lean'
    return re.findall(r'^import\s+(AlgebraicJacobian[\w.]*)', open(p).read(), re.M) if os.path.exists(p) else []
seen, stack = set(), ['AlgebraicJacobian']
while stack:
    m = stack.pop()
    if m not in seen:
        seen.add(m); stack += imports(m)
disk = set()
for root,_,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'):
            disk.add(os.path.join(root,f)[:-5].replace('/','.'))
print('rooted-closure size (incl root):', len(seen))
print('on disk:', len(disk))
print('UNROOTED:', sorted(disk - seen))
seen2, stack2 = set(), ['AlgebraicJacobian.Jacobian']
while stack2:
    m = stack2.pop()
    if m not in seen2:
        seen2.add(m); stack2 += imports(m)
print('reachable from headline:', len(seen2))
